import { t } from '@lingui/core/macro';
import { useMemo } from 'react';

import { ApiEndpoints } from '@lib/enums/ApiEndpoints';
import { ModelType } from '@lib/enums/ModelType';
import { UserRoles } from '@lib/enums/Roles';
import { apiUrl } from '@lib/functions/Api';
import type { TableFilter } from '@lib/types/Filters';
import { AddItemButton } from '../../components/buttons/AddItemButton';
import { ProgressBar } from '../../components/items/ProgressBar';
import { RenderUser } from '../../components/render/User';
import { useBuildOrderFields } from '../../forms/BuildForms';
import { useCreateApiFormModal } from '../../hooks/UseForm';
import { useTable } from '../../hooks/UseTable';
import { useGlobalSettingsState } from '../../states/SettingsStates';
import { useUserState } from '../../states/UserState';
import {
  BooleanColumn,
  CreationDateColumn,
  DateColumn,
  PartColumn,
  ProjectCodeColumn,
  ReferenceColumn,
  ResponsibleColumn,
  StartDateColumn,
  StatusColumn,
  TargetDateColumn
} from '../ColumnRenderers';
import {
  AssignedToMeFilter,
  CompletedAfterFilter,
  CompletedBeforeFilter,
  CreatedAfterFilter,
  CreatedBeforeFilter,
  HasProjectCodeFilter,
  IssuedByFilter,
  MaxDateFilter,
  MinDateFilter,
  OrderStatusFilter,
  OutstandingFilter,
  OverdueFilter,
  PartCategoryFilter,
  ProjectCodeFilter,
  ResponsibleFilter,
  StartDateAfterFilter,
  StartDateBeforeFilter,
  TargetDateAfterFilter,
  TargetDateBeforeFilter
} from '../Filter';
import { InvenTreeTable } from '../InvenTreeTable';
import { Button, Group, Anchor, Text, Image, Tooltip } from '@mantine/core';
import { IconLink } from '@tabler/icons-react';
import { cancelEvent } from '@lib/functions/Events';

/*
 * Construct a table of build orders, according to the provided parameters
 */
export function BuildOrderTable({
  partId,
  parentBuildId,
  salesOrderId
}: Readonly<{
  partId?: number;
  parentBuildId?: number;
  salesOrderId?: number;
}>) {
  const globalSettings = useGlobalSettingsState();
  const table = useTable(!!partId ? 'buildorder-part' : 'buildorder-index');

  const tableColumns = useMemo(() => {
    return [
      ReferenceColumn({}),
      // {
      //   accessor: 'part',
      //   sortable: true,
      //   switchable: false,
      //   render: (record: any) => PartColumn({ part: record.part_detail })
      // },
      {
        accessor: 'part',
        sortable: true,
        switchable: false,
        render: (record: any) => {
          const part = record?.part_detail;
          if (!part) return t`No Part`;

          const url = `/web/part/${part.pk}/details`;

          return (
            <Anchor
              href={url}
              onClick={(event: any) => {
                cancelEvent(event); // prevent full page reload
                window.open(url, '_blank', 'noopener,noreferrer'); // open in new tab
              }}
              title={part.name}
            >
              {/* Reuse your existing PartColumn renderer */}
              {PartColumn({ part })}
            </Anchor>
          );
        }
      },
      {
        accessor: 'part_detail.IPN',
        sortable: true,
        switchable: true,
        title: t`IPN`
      },
      {
        accessor: 'part_detail.revision',
        title: t`Revision`,
        sortable: true,
        defaultVisible: false
      },
      {
        accessor: 'title',
        sortable: false
      },
      {
        accessor: 'completed',
        sortable: true,
        switchable: false,
        render: (record: any) => (
          <ProgressBar
            progressLabel={true}
            value={record.completed}
            maximum={record.quantity}
          />
        )
      },
      StatusColumn({ model: ModelType.build }),
      ProjectCodeColumn({
        defaultVisible: false
      }),
      {
        accessor: 'level',
        sortable: true,
        switchable: true,
        hidden: !parentBuildId,
        defaultVisible: false
      },
      {
        accessor: 'priority',
        sortable: true,
        defaultVisible: false
      },
      BooleanColumn({
        accessor: 'external',
        title: t`External`,
        sortable: true,
        switchable: true,
        hidden: !globalSettings.isSet('BUILDORDER_EXTERNAL_BUILDS')
      }),
      CreationDateColumn({
        defaultVisible: false
      }),
      StartDateColumn({
        defaultVisible: false
      }),
      TargetDateColumn({}),
      DateColumn({
        accessor: 'completion_date',
        title: t`Completion Date`,
        sortable: true
      }),
      {
        accessor: 'issued_by',
        sortable: true,
        render: (record: any) => (
          <RenderUser instance={record?.issued_by_detail} />
        )
      },
      ResponsibleColumn({})
    ];
  }, [parentBuildId, globalSettings]);

  const tableFilters: TableFilter[] = useMemo(() => {
    const filters: TableFilter[] = [
      OutstandingFilter(),
      OrderStatusFilter({ model: ModelType.build }),
      OverdueFilter(),
      AssignedToMeFilter(),
      MinDateFilter(),
      MaxDateFilter(),
      CreatedBeforeFilter(),
      CreatedAfterFilter(),
      TargetDateBeforeFilter(),
      TargetDateAfterFilter(),
      StartDateBeforeFilter(),
      StartDateAfterFilter(),
      {
        name: 'has_target_date',
        type: 'boolean',
        label: t`Has Target Date`,
        description: t`Show orders with a target date`
      },
      {
        name: 'has_start_date',
        type: 'boolean',
        label: t`Has Start Date`,
        description: t`Show orders with a start date`
      },
      CompletedBeforeFilter(),
      CompletedAfterFilter(),
      ProjectCodeFilter(),
      HasProjectCodeFilter(),
      IssuedByFilter(),
      ResponsibleFilter(),
      {
        name: 'external',
        label: t`External`,
        description: t`Show external build orders`,
        active: globalSettings.isSet('BUILDORDER_EXTERNAL_BUILDS')
      },
      PartCategoryFilter()
    ];

    // If we are filtering on a specific part, we can include the "include variants" filter
    if (!!partId) {
      filters.push({
        name: 'include_variants',
        type: 'boolean',
        label: t`Include Variants`,
        description: t`Include orders for part variants`
      });
    }

    return filters;
  }, [partId, globalSettings]);

  const user = useUserState();

  const buildOrderFields = useBuildOrderFields({
    create: true,
    modalId: 'create-build-order'
  });

  const newBuild = useCreateApiFormModal({
    url: ApiEndpoints.build_order_list,
    title: t`Add Build Order`,
    modalId: 'create-build-order',
    fields: buildOrderFields,
    initialData: {
      part: partId,
      sales_order: salesOrderId,
      parent: parentBuildId
    },
    follow: true,
    modelType: ModelType.build
  });

const tableActions = useMemo(() => {
  return [
    <AddItemButton
      hidden={!user.hasAddRole(UserRoles.build)}
      tooltip={t`Add Build Order`}
      onClick={() => newBuild.open()}
      key="add-build-order"
    />,
    <Group justify="flex-start" key="combined-build-orders">
      <Button
        size="xs"
        // color="blue"
        onClick={() => {
          const selected = table.selectedRecords || [];

          console.clear();
          console.log("▶ Selected build orders:", selected);
          console.log("▶ Selected count:", selected.length);
          console.log("▶ Selected statuses:", selected.map(row => row.status));

          if (selected.length < 2) {
            console.warn("❌ Less than 2 build orders selected");
            window.alert(t`Please select at least two build orders`);
            return;
          }

          const hasBlockedStatus = selected.some(row => {
            const status = parseInt(row.status);
            return status === 30 || status === 40; // completed or cancelled
          });

          console.log("▶ Has completed or cancelled:", hasBlockedStatus);

          if (hasBlockedStatus) {
            console.warn("❌ One or more selected builds are completed or cancelled");
            window.alert(
              t`Selected build orders include a completed or cancelled one. Please deselect them.`
            );
            return;
          }

          const build_ids = selected.map(row => row.pk).join(',');
          console.log("✅ Triggering CSV download for builds:", build_ids);

          window.location.href = `/api/build/export-combined-allocation/?build_ids=${build_ids}`;
        }}
      >
        <span className="fas fa-layer-group" style={{ marginRight: 6 }} />
        {t`Combined Build Orders`}
      </Button>
    </Group>
  ];
}, [user, table]);


  return (
    <>
      {newBuild.modal}
      <InvenTreeTable
        url={apiUrl(ApiEndpoints.build_order_list)}
        tableState={table}
        columns={tableColumns}
        props={{
          params: {
            part: partId,
            ancestor: parentBuildId,
            sales_order: salesOrderId,
            part_detail: true
          },
          tableActions: tableActions,
          tableFilters: tableFilters,
          modelType: ModelType.build,
          enableSelection: true,
          enableReports: true,
          enableDownload: true
        }}
      />
    </>
  );
}
